19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE = 0.1;
21	
22	/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
23	const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
24	
25	const BASE_PREMIUMS: Record<string, number> = {
26	  sword: 100,
27	  amulet: 60,
28	  staff: 80,
29	  potion: 40,
30	  rune: 25,
31	};
32	
33	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
34	
35	const quotePremium = (step: QuoteStep): number => {
36	  const policyBasePremium = step.items.reduce(
37	    (sum, item) => sum + itemBasePremium(item),
38	    0,
39	  );
40	  const premiumAfterFirstInsuranceSurcharge =
41	    policyBasePremium * (1 + FIRST_INSURANCE_SURCHARGE);
42	
43	  return roundUp(premiumAfterFirstInsuranceSurcharge + PROCESSING_FEE);
44	};
45	
46	export const runScenario = (scenario: Scenario): ScenarioResults => ({
47	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
48	});
