const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];

/** The policy base premium is the sum of the base premiums of its items. */
const policyBasePremium = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemBasePremium(item), 0);

const quotePremium = (step: QuoteStep): number => {
  const premiumAfterFirstInsuranceSurcharge =
    policyBasePremium(step.items) * (1 + FIRST_INSURANCE_SURCHARGE);

  return roundUp(premiumAfterFirstInsuranceSurcharge + PROCESSING_FEE);
};
